// The model answers JSON text, in the Response Format of its model node. Read it into `output`.
// Also takes {"output": {...}} or a ```json block, so a good answer never stops the workflow.
const text = $json.text.trim().replace(/^```(?:json)?\s*|\s*```$/g, '');
const answer = JSON.parse(text);
const wrapped = answer.output && typeof answer.output === 'object' && Object.keys(answer).length === 1;
return { json: { output: wrapped ? answer.output : answer } };

